V=Path(__file__).resolve().parent; L=V.parents[1]; R=V.parents[4]
BASE='4f65c502beabb38bb3365920005e2e6f90ea13f0'
def read(p): return json.loads(p.read_text('utf8'))
def save(p,d): p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
def write(p,s): p.write_text(s,encoding='utf8',newline='\n')
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def href(p): return os.path.relpath(p,V).replace('\\','/')
def esc(s): return html.escape(s)
b=read(L/'book.json')
assert b['revision'].startswith('V34')
sources=[
 dict(id='asha',title='ASHA: Communication Milestones, 4 to 5 Years',url='https://www.asha.org/public/developmental-milestones/communication-milestones-4-to-5-years/',supported='Clear story connections, location words, categories, prediction, conversation and child-led retelling are useful shared-reading activities.',application='Use a few concrete language opportunities already shown in the art. This is an editorial application, not a tested intervention or SLP sign-off.'),
 dict(id='aap',title='AAP: Books to Teach Kids About Feelings and Resilience',url='https://www.healthychildren.org/English/healthy-living/emotional-wellness/Building-Resilience/Pages/recommended-reading-books-to-teach-kids-about-feelings-and-resilience.aspx',supported='Shared reading and conversation about characters’ feelings can support discussion of emotions and other people’s perspectives.',application='Let visible feelings lead to an understandable choice and action. A value is dramatized through the story; no clinical benefit is promised.'),
 dict(id='harvard',title='Harvard Center on the Developing Child: Activities for 3 to 5 Years',url='https://developingchild.harvard.edu/wp-content/uploads/2024/10/Executive-Function-Activities-for-3-to-5-year-olds.pdf',supported='Pretend play, planning, sorting and revisiting stories provide opportunities to practise organizing ideas and actions.',application='Offer a short optional retelling or gentle-play activity after reading. Reading this book alone is not evidence of improved executive function.')]
diagnosis=[
 dict(issue='A helpful heroine with little development',evidence='On 4 Roshan immediately offers to clean; on 5 Daddy gives a useful strategy. She seldom needs that support in a visible choice.',change='Give her one honest question about beginning, then show her choose a small first task. Confidence can grow without a new failure, a crying pose or a dangerous setback.'),
 dict(issue='A chain of errands needs a shared purpose',evidence='Bath, pool, playroom and paints currently read as completed jobs. The care beneath those jobs is often left implicit.',change='Connect cleaning to comfort, freedom, gentle play and a shared place to rest. Keep practical responsibility without making tidiness the measure of a good person.'),
 dict(issue='Intent is explained; impact is underdeveloped',evidence='On 18 the bunnies want to play while Baby Eagle is pinned. On 20 they say Sorry and We were just playing, but there is no clear next behaviour.',change='Give Eagle words for his boundary and the bunnies a small concrete repair. Their existing exact lines are prior owner wording: the proposed second-bubble change is a decision, not silently implemented.'),
 dict(issue='Rumi can become a participant',evidence='Rumi is helped on 10–16 and joins the group on 26, but her choice to help is not voiced.',change='Bridge the hug to later teamwork. Rumi helps because she chooses to join in; gratitude does not create a debt or an obligation to repay Roshan.'),
 dict(issue='The finale can show receiving help',evidence='A quiet request on 23 leads to care on 25–26. Roshan currently appears to know exactly what to do.',change='Let Roshan ask her friends to help with the big job. Helping others and accepting help can belong to the same child.'),
 dict(issue='Appearance carries much of the payoff',evidence='The rainbow transformation is wonderful fantasy, followed by We helped your rainbow shine on 31.',change='Keep the exact reveal. Put the emotional reward in comfort, thanks and company. Show care before the change; nobody earns belonging by becoming clean or pretty.'),
 dict(issue='Physical cause and magical cause can be clearer',evidence='A cup blocks the fountain; pool magic makes rainbow water. Both events use Whoosh, with little explanation.',change='State the physical blockage plainly. Keep rainbow water explicitly magical; no science claim about real water changing colour when rubbish is removed.'),
 dict(issue='A rear cover discloses the answer',evidence='The current rear shows the entire cooperative wash: Grand Puff is a friend who is helped, not an unresolved mystery.',change='Use an early threshold scene and a beginning-focused question. Omit washing, rainbow Puff, the transformation, the sleeping finale and the solution. The front remains a separate later cover-review decision.')]
proposals=[
 (4,'“What a big mess!” said Roshan.\n“Where do we start?”','Small-step confidence','Gives Roshan a real question without adding an unseen breakdown. Daddy’s next-page advice now answers her.','Existing thoughtful hall faces; no new action.'),
 (7,'“I’ll start with the sink,” said Roshan.\nRound and round went her sponge.','Agency and planning','The first small job becomes her decision. The existing sink wiping supplies the evidence.','Existing whole sink-action cutout.'),
 (10,'Rumi was stuck under the gunk.\n“Can you help me?”','Naming a need','A simple help request can recur at the final door. Words come from the trapped character rather than a lesson from the narrator.','Same pool/under-gunk scene; offscreen speech is caption dialogue.'),
 (14,'A cup blocked the fountain.\nRoshan pulled it free. Whoosh!','Cause and effect','Names what prevented the flow and what changed it. The pool’s rainbow water stays magic on 13.','Existing cup-removal scene.'),
 (16,'“Thank you!” said Rumi.\n“Let’s help together.”','Agency and cooperation','The hug leads to a voluntary shared purpose. Avoid implying she owes help in return for rescue.','Existing contour hug; caption reflow will be needed.'),
 (18,'Two dust bunnies wanted to play.\nBut Baby Eagle could not get free!','Perspective and impact','Retains the playful intent and literal two-bunny trap. The next scene supplies space and release.','Existing trap; preserve exactly two canonical little puffs.'),
 (20,'“I need some space,” said Baby Eagle.\n“Let’s play gently,” said Roshan.','Boundaries and repair','Lets the affected friend express a need. Proposed response: retain Sorry! and change the second bubble to We’ll be gentle. This exact owner-line change needs a choice.','Keep Eagle dominant and bunnies tiny. Local lower-bank acting: one listens, one carefully handles a soft toy; no extra giant speech bubble.'),
 (21,'Roshan put the paints together\nand the brushes in their pot. Tidy, tidy!','Sorting and useful vocabulary','A concrete grouping rule gives the existing art-room job a learning purpose. Verify the brush-pot detail against native artwork before implementation.','Keep the accepted sorting composition; no invented painting/craft activity.'),
 (24,'Grand Puff!\nHe was covered in dust.\nHe looked tired and sad.','Reading feelings','Names the cues in his existing unwell expression. The following page offers care before any transformation.','Existing main Grand Puff only; no boss-shaped border cameo.'),
 (26,'“Can you help me?” asked Roshan.\n“Yes!” said Rumi.\nTogether, they washed Grand Puff. Scrub, scrub!','Asking and accepting help','Mirrors the earlier requests. Roshan can be a helper who also needs others; the whole illustrated group still participates.','Exact four-helper source scene; layout and speaker clarity must be checked.'),
 (29,'Down came Grand Puff, soft and small.\n“I feel better!” he said.','Expressing a changed feeling','Makes the personal payoff understandable without tying his worth to his new colours.','Exact existing landing: no redraw or pose change.'),
 (31,'“Thank you for helping me,” said Grand Puff.\n“Come and rest with us!” said Roshan.','Gratitude and belonging','Closes with comfort and company instead of congratulating a new appearance.','Existing welcome arrangement; exact attribution/line fit to be checked.')]
rows=[]
for n,text,skill,why,art in proposals:
 rows.append(dict(page=n,before=b['pages'][n-1]['text'],proposed=text,learning=skill,reason=why,art_scope=art,status='PROPOSED_NOT_APPLIED'))
learning=[
 dict(layer='Main emotional thread',aim='Notice a need; listen; help gently; accept help; make room for a friend.',vehicle='Rumi’s request, Baby Eagle’s boundary, Roshan’s request and Grand Puff’s welcome.',limit='One connected theme. Do not add a separate moral after every job.'),
 dict(layer='Supporting practical confidence',aim='Begin a large task with one manageable step.',vehicle='Roshan’s opening question, Daddy’s advice, her sink choice and the existing closing refrain.',limit='Do not force a new failure plot or make the child responsible for every adult-sized mess.'),
 dict(layer='Embedded thinking and language',aim='Name, sort, compare, explain a cause, sequence and retell.',vehicle='Two bunnies; stuck/free; dirty/clean; cup/flow; paint/brush categories; under/behind; first/then.',limit='Choose a few accurate opportunities; no counting hunt, rainbow quiz or lesson box on every page.'),
 dict(layer='Growing reading participation',aim='Move from joining a read-aloud to recognizing familiar language.',vehicle='Scrub, scrub; Scoop, scoop; help; gently; one little job at a time. Adult models fuller sentences.',limit='Recognition and memorized refrains are not proof of decoding. Keep ordinary phonics learning separate from this story.')]
prompts=[
 dict(pages='4–7',prompt='What little job could Roshan start with?',transfer='Choose one small part of a real shared tidy-up.'),
 dict(pages='14',prompt='What changed when the cup came out?',transfer='Retell the blockage and flowing-water sequence. Real water flow and magical rainbow colour have different causes.'),
 dict(pages='18–20',prompt='How can you tell Baby Eagle does not like this game?',transfer='Practise asking for space and stopping gently during pretend play.'),
 dict(pages='23–26',prompt='Who asked for help? Who helped?',transfer='Take turns being the helper and the person who asks.'),
 dict(pages='31–32',prompt='What made Grand Puff feel welcome?',transfer='Talk about a small way to include someone, with no right answer required.')]
review=dict(id='chapter-one-v35-story-value-review',baseline=BASE,status='PROPOSAL_ONLY_OWNER_THEME_RESPONSE_PENDING',word_count_current_captions=sum(len(re.findall(r'\b[\w’-]+\b',p['text'])) for p in b['pages']),recommendation='Kindness through attentive action is primary; small steps and cooperation support it. Keep fantasy, humour, the accepted plot, 32 interior pages and exact finale staging.',owner_question='Which emotional emphasis should the next draft carry: kindness first, small-step confidence first, or equal weight?',diagnosis=diagnosis,learning_design=learning,proposed_changes=rows,apology_bubble_decision=dict(current=['Sorry!','We were just playing!'],proposed=['Sorry!','We’ll be gentle.'],status='PRIOR_EXACT_OWNER_WORDING_CHANGE_NOT_APPLIED'),unchanged_pages=[n for n in range(1,33) if n not in [z['page'] for z in rows]],preserved=['34 total pages including covers','Cooperative care, no combat','Exact jump, landing and bubble-pile rest','Rumi residence versus entrapment distinction','Little puffs only in banks, small figures, blue stationery, whole alpha cutouts or full art','Unprompted hidden cameos; no child-facing search cue'],optional_after_reading=dict(location='Separate grown-up card outside the 34-page story',use='Choose one invitation on a later reread; allow pointing, acting or a short answer, and follow the child’s interest.',prompts=prompts),sources=sources,acceptance='Editorial inference only; not tested developmental benefit, phonics instruction or qualified SLP sign-off. Manuscript changes await the owner’s theme decision.')
